const raw = String($env.WATCH_TARGET_URLS || 'https://example.com,https://n8n.example.com');
const targets = raw.split(',').map((u) => u.trim()).filter((u) => u.startsWith('https://') || u.startsWith('http://'));
const maxLatencyMs = Number($env.WATCH_MAX_LATENCY_MS || 2500);
const pricePattern = String($env.WATCH_PRICE_REGEX || '');

return targets.map((url) => ({
  json: {
    url,
    maxLatencyMs,
    pricePattern,
    checkedAt: new Date().toISOString(),
    startedMs: Date.now()
  }
}));

const items = $input.all();
const srcItems = $('Nap danh sach URL giam sat').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const meta = srcItems[i]?.json || {};
  const statusCode = Number(resp.statusCode || 0);
  const elapsedMs = Math.max(1, Date.now() - Number(meta.startedMs || Date.now()));
  const bodyStr = typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body || '');
  const reasons = [];

  if (statusCode < 200 || statusCode >= 400) {
    reasons.push(`HTTP loi (${statusCode || 'TIMEOUT / SSL ERROR'})`);
  }
  if (elapsedMs > Number(meta.maxLatencyMs || 2500)) {
    reasons.push(`Phan hoi cham (${elapsedMs}ms)`);
  }
  if (meta.url && meta.url.startsWith('http://')) {
    reasons.push('Chua bat HTTPS/SSL');
  }
  let matchedPrice = '';
  if (meta.pricePattern) {
    try {
      const rx = new RegExp(meta.pricePattern, 'i');
      const m = bodyStr.match(rx);
      if (m) matchedPrice = m[0];
    } catch (_err) {
      reasons.push('Regex gia khong hop le');
    }
  }

  const shouldAlert = reasons.length > 0;
  results.push({
    json: {
      url: meta.url,
      statusCode,
      elapsedMs,
      matchedPrice,
      shouldAlert,
      alertText: [
        'CANH BAO GIAM SAT WEBSITE / SSL / GIA',
        `URL: ${meta.url}`,
        `Trang thai: HTTP ${statusCode || 'ERR'} (${elapsedMs}ms)`,
        `Van de: ${reasons.join('; ')}`,
        matchedPrice ? `Gia ghi nhan: ${matchedPrice}` : 'Khong cau hinh theo doi gia',
        `Thoi diem: ${meta.checkedAt}`
      ].join('\n')
    }
  });
}
return results;
